def compute(payload):
    """对每个 open 事件按其原始位置（十进制字符串）建立初始状态，字段同最终 stores 项。"""
    result = {}
    for index, event in enumerate(payload["events"]):
        if event.get("op") != "open":
            continue
        result[str(index)] = {
            "backend": event["backend"],
            "state": "open",
            "job": None,
            "revision": event.get("revision", 0),
            "closed_at": None,
            "updates": 0,
        }
    return result

def compute(payload):
    """对每个 complete 事件按原始位置记录 [正常完成事件名,新 revision 或 null]。

    取消与关闭优先级由整合逻辑决定，这里只记录正常完成的效果：
    changed=true 时事件名为 snapshot_updated 且新 revision 为事件中的 revision；
    changed=false 时事件名为 poll_unchanged 且新 revision 为 null。
    """
    result = {}
    for index, event in enumerate(payload.get("events", [])):
        if event.get("op") != "complete":
            continue
        changed = bool(event.get("changed", False))
        if changed:
            name = "snapshot_updated"
            revision = event.get("revision")
        else:
            name = "poll_unchanged"
            revision = None
        result[str(index)] = [name, revision]
    return result

import json
import sys
from pathlib import Path

root = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(root))

from components.store_initializers.work import compute


class TestStoreInitializers(unittest.TestCase):
    def test_open_builds_initial_state(self):
        payload = {"events": [
            {"time": 0, "store": "s", "op": "open", "backend": "git"},
            {"time": 1, "store": "s", "op": "close"},
        ]}
        result = compute(payload)
        self.assertEqual(result, {
            "0": {
                "backend": "git",
                "state": "open",
                "job": None,
                "revision": 0,
                "closed_at": None,
                "updates": 0,
            }
        })

    def test_revision_default_and_explicit(self):
        payload = {"events": [
            {"time": 0, "store": "a", "op": "open", "backend": "s3"},
            {"time": 1, "store": "b", "op": "open", "backend": "azure", "revision": 7},
        ]}
        result = compute(payload)
        self.assertEqual(result["0"]["revision"], 0)
        self.assertEqual(result["1"]["revision"], 7)
        self.assertEqual(result["1"]["backend"], "azure")

    def test_non_open_events_ignored(self):
        payload = {"events": [
            {"time": 0, "store": "s", "op": "poll", "job": "j"},
            {"time": 1, "store": "s", "op": "open", "backend": "oci"},
        ]}
        result = compute(payload)
        self.assertEqual(list(result.keys()), ["1"])


if __name__ == "__main__":
    unittest.main()

