import json, unittest, sys
sys.path.insert(0, "/workspace")
from components.completion_effects.work import compute

class TestCompletionEffects(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(compute({"events": []}), {})

    def test_changed_true(self):
        payload = {"events": [
            {"time": 0, "store": "s", "op": "open", "backend": "git"},
            {"time": 1, "store": "s", "op": "poll", "job": "j"},
            {"time": 2, "store": "s", "op": "complete", "job": "j", "changed": True, "revision": 7},
        ]}
        self.assertEqual(compute(payload), {"2": ["snapshot_updated", 7]})

    def test_changed_false(self):
        payload = {"events": [
            {"time": 0, "store": "s", "op": "open", "backend": "git"},
            {"time": 1, "store": "s", "op": "poll", "job": "j"},
            {"time": 2, "store": "s", "op": "complete", "job": "j", "changed": False},
        ]}
        self.assertEqual(compute(payload), {"2": ["poll_unchanged", None]})

    def test_position_keying(self):
        payload = {"events": [
            {"time": 0, "store": "s", "op": "open", "backend": "git"},
            {"time": 1, "store": "s", "op": "complete", "job": "a", "changed": True, "revision": 1},
            {"time": 2, "store": "s", "op": "complete", "job": "b", "changed": False},
        ]}
        self.assertEqual(compute(payload), {"1": ["snapshot_updated", 1], "2": ["poll_unchanged", None]})

if __name__ == "__main__":
    unittest.main()
