            st = stores[key]
            st["state"] = "open"
            emit(time, store, "opened")
            continue

        if op == "poll":
            key = store_key[store]
            st = stores[key]
            if st["state"] == "open":
                if st["job"] is None:
                    st["job"] = ev["job"]
                    in_flight[store] = ev["job"]
                    emit(time, store, "poll_started", ev["job"])
                else:
                    emit(time, store, "poll_coalesced")
            else:
                emit(time, store, "poll_rejected")
            continue

        if op == "complete":
            job = ev["job"]
            key = store_key[store]
            st = stores[key]
            changed = bool(ev.get("changed", False))
            cancelled = store in closing
            if cancelled:
